mapper.sql:
FROM t_record r
LEFT JOIN t_category c ON c.id = r.category_id

    r.deleted_at IS NULL
    AND r.type = #{condition.type}
    AND r.status = #{condition.status}
    AND r.category_id = #{condition.categoryId}

        AND (r.title LIKE #{condition.keywordPattern} ESCAPE '/'
          OR r.description LIKE #{condition.keywordPattern} ESCAPE '/')

mapper.select:
SELECT r.id, r.type, r.status, r.title, r.category_id, c.name AS category_name,
       r.location, r.occurred_at, r.created_at


LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE t_record
SET status = #{status}
WHERE id = #{id} AND deleted_at IS NULL

UPDATE t_record
SET deleted_at = #{deletedAt}
WHERE id = #{id} AND deleted_at IS NULL

mapper.select:
SELECT id, title, description, category_id, location
FROM t_record

    deleted_at IS NULL AND status = 'PENDING'
    AND type = #{type}
    AND category_id = #{categoryId}

ORDER BY created_at DESC, id DESC
LIMIT #{limit}
